import pytest

def test_include_router_self():
    router = APIRouter()

    @router.get("/test")
    def test_route():
        return {"message": "hello"}

    with pytest.raises(FastAPIError) as excinfo:
        router.include_router(router)

    assert "Cannot include a router into itself" in str(excinfo.value)

def test_fastapi_include_router_self():
    app = FastAPI()

    with pytest.raises(FastAPIError) as excinfo:
        app.include_router(app.router)

    assert "Cannot include a router into itself" in str(excinfo.value)

if __name__ == "__main__":
    try:
        test_include_router_self()
        print("test_include_router_self passed")
        test_fastapi_include_router_self()
        print("test_fastapi_include_router_self passed")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e

